function renderScene(api, input) {
  const canvas = api.canvas;
  const ctx = canvas.getContext('2d');
  const params = input.parameters;
  const state = params.state;
  const viewport = params.viewport;
  const width = viewport.width;
  const height = viewport.height;

  // Clear canvas
  ctx.clearRect(0, 0, width, height);

  // Determine if phone or tablet
  const isPhone = width <= 500;

  // Layout constants
  const rubberBandY = isPhone ? height * 0.4 : height * 0.45;
  const rubberBandLength = isPhone ? width * 0.7 : width * 0.6;
  const rubberBandLeft = (width - rubberBandLength) / 2;
  const rubberBandRight = rubberBandLeft + rubberBandLength;
  const rubberBandThickness = isPhone ? 6 : 8;

  // Pluck positions
  const pluckX = rubberBandLeft + rubberBandLength * 0.3;
  const pluckY = rubberBandY;

  // Amplitude parameters
  const lightAmplitude = isPhone ? 15 : 20;
  const strongAmplitude = isPhone ? 40 : 55;
  let amplitude = 0;
  let pluckOffset = 0;

  // State handling
  if (state === 'initial' || state === 'static_fallback') {
    amplitude = 0;
    pluckOffset = 0;
  } else if (state === 'key_process') {
    // Show both light and strong plucks side by side? Or animate?
    // For key_process, we'll show the rubber band being plucked with strong force.
    amplitude = strongAmplitude;
    pluckOffset = strongAmplitude;
  } else if (state === 'final') {
    // Show the result: larger amplitude for strong pluck
    amplitude = strongAmplitude;
    pluckOffset = strongAmplitude;
  } else if (state === 'paused') {
    amplitude = strongAmplitude * 0.5;
    pluckOffset = strongAmplitude * 0.5;
  } else if (state === 'resumed') {
    amplitude = strongAmplitude;
    pluckOffset = strongAmplitude;
  } else if (state === 'post_interaction') {
    amplitude = strongAmplitude;
    pluckOffset = strongAmplitude;
  } else if (state === 'reduced_motion') {
    amplitude = strongAmplitude * 0.3;
    pluckOffset = strongAmplitude * 0.3;
  }

  // Draw rubber band
  ctx.beginPath();
  ctx.strokeStyle = '#8B4513';
  ctx.lineWidth = rubberBandThickness;
  ctx.moveTo(rubberBandLeft, rubberBandY);
  // Draw a curve representing the plucked shape
  const cp1x = rubberBandLeft + rubberBandLength * 0.25;
  const cp1y = rubberBandY - pluckOffset;
  const cp2x = rubberBandLeft + rubberBandLength * 0.75;
  const cp2y = rubberBandY - pluckOffset;
  ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, rubberBandRight, rubberBandY);
  ctx.stroke();

  // Draw endpoints (pegs)
  ctx.fillStyle = '#A9A9A9';
  ctx.beginPath();
  ctx.arc(rubberBandLeft, rubberBandY, isPhone ? 8 : 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(rubberBandRight, rubberBandY, isPhone ? 8 : 10, 0, Math.PI * 2);
  ctx.fill();

  // Draw plucking hand indicator (simple arrow or hand)
  if (pluckOffset > 0) {
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(pluckX, pluckY - pluckOffset, isPhone ? 12 : 15, 0, Math.PI * 2);
    ctx.fill();
    // Draw arrow pointing to pluck point
    ctx.strokeStyle = '#FF4500';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(pluckX, pluckY - pluckOffset - (isPhone ? 20 : 25));
    ctx.lineTo(pluckX, pluckY - pluckOffset - (isPhone ? 5 : 8));
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(pluckX - 5, pluckY - pluckOffset - (isPhone ? 15 : 20));
    ctx.lineTo(pluckX, pluckY - pluckOffset - (isPhone ? 5 : 8));
    ctx.lineTo(pluckX + 5, pluckY - pluckOffset - (isPhone ? 15 : 20));
    ctx.stroke();
  }

  // Labels
  ctx.font = isPhone ? '14px sans-serif' : '18px sans-serif';
  ctx.fillStyle = '#000';
  ctx.textAlign = 'center';
  ctx.fillText('橡皮筋', width / 2, rubberBandY - (isPhone ? 50 : 60));

  // Amplitude indicator
  if (amplitude > 0) {
    ctx.strokeStyle = '#FF0000';
    ctx.lineWidth = 1;
    ctx.setLineDash([5, 3]);
    ctx.beginPath();
    ctx.moveTo(pluckX, rubberBandY);
    ctx.lineTo(pluckX, rubberBandY - amplitude);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#FF0000';
    ctx.font = isPhone ? '12px sans-serif' : '14px sans-serif';
    ctx.fillText('振幅', pluckX, rubberBandY - amplitude - 5);
  }

  // Force label
  ctx.fillStyle = '#000';
  ctx.font = isPhone ? '12px sans-serif' : '14px sans-serif';
  if (state === 'initial' || state === 'static_fallback') {
    ctx.fillText('轻拨', pluckX, rubberBandY + (isPhone ? 30 : 40));
  } else {
    ctx.fillText('重拨', pluckX, rubberBandY + (isPhone ? 30 : 40));
  }

  // Teaching facts
  ctx.fillStyle = '#000';
  ctx.font = isPhone ? '12px sans-serif' : '14px sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText('固定同一根橡皮筋，只改变拨动的力气。', 10, height - 40);
  ctx.fillText('轻拨：振幅小，响度小；重拨：振幅大，响度大。', 10, height - 20);
  ctx.fillText('音调不变。', 10, height - 5);

  api.emit('render_complete');
}

