function renderScene(api, input) {
  const canvas = api.canvas;
  const ctx = canvas.getContext('2d');
  const state = input.parameters.state;
  const viewport = input.parameters.viewport;
  const width = viewport[0];
  const height = viewport[1];

  // Clear canvas
  ctx.clearRect(0, 0, width, height);

  // Define colors
  const colors = {
    background: '#f9f9f9',
    fence: '#8B4513',
    wall: '#555555',
    area: '#90EE90',
    text: '#000000',
    highlight: '#FFD700',
    axis: '#000000',
    curve: '#0000FF',
    point: '#FF0000'
  };

  // Helper function to draw text
  function drawText(text, x, y, fontSize, color, align) {
    ctx.fillStyle = color;
    ctx.font = `${fontSize}px Arial`;
    ctx.textAlign = align || 'left';
    ctx.fillText(text, x, y);
  }

  // Helper function to draw rectangle
  function drawRect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, w, h);
  }

  // Helper function to draw line
  function drawLine(x1, y1, x2, y2, color, lineWidth) {
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth || 1;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  // Helper function to draw circle
  function drawCircle(x, y, radius, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, 2 * Math.PI);
    ctx.fill();
  }

  // Layout parameters based on viewport
  let layout;
  if (width === 390 && height === 632) { // phone
    layout = {
      graphX: 20, graphY: 20, graphW: 350, graphH: 200,
      fenceX: 20, fenceY: 240, fenceW: 350, fenceH: 200,
      textX: 20, textY: 460, textW: 350, textH: 150,
      fontSizeSmall: 12, fontSizeMedium: 14, fontSizeLarge: 16
