  } else { // tablet
    layout = {
      graphX: 50, graphY: 30, graphW: 400, graphH: 250,
      fenceX: 500, fenceY: 30, fenceW: 474, fenceH: 250,
      textX: 50, textY: 310, textW: 924, textH: 388,
      fontSizeSmall: 14, fontSizeMedium: 18, fontSizeLarge: 22
    };
  }

  // Draw background
  drawRect(0, 0, width, height, colors.background);

  // State-specific rendering
  if (state === 'static_fallback') {
    // Render static fallback: worked steps
    const steps = [
      "平方项始终非负",
      "平方项为零时减去量最小",
      "因此面积达到最大值"
    ];
    let y = layout.textY + 30;
    drawText("推理步骤:", layout.textX, y, layout.fontSizeLarge, colors.text, 'left');
    y += 30;
    steps.forEach(step => {
      drawText(step, layout.textX + 20, y, layout.fontSizeMedium, colors.text, 'left');
      y += 25;
