    // Draw parabola with a point not at vertex
    const pointX = graphX + 3 * scaleX;
    const pointY = graphY + graphH - ( -9 + 30 ) * scaleY; // y = -9+30=21
    drawCircle(pointX, pointY, 5, colors.point);
    drawText('(3,21)', pointX + 10, pointY - 10, layout.fontSizeSmall, colors.text);

    // Rectangle with x=3
    const demoRectW = 3 * (fenceW - 30) / 10;
    const demoRectH = 4 * (fenceH - 40) / 10; // 10-2*3=4
    drawRect(rectX, rectY, demoRectW, demoRectH, colors.area);
    drawText('x=3', rectX + demoRectW/2, rectY - 5, layout.fontSizeSmall, colors.text, 'center');
    drawText('10-2x=4', rectX + demoRectW + 5, rectY + demoRectH/2, layout.fontSizeSmall, colors.text, 'left');

    drawText('平方项为正，面积未达最大。', textX, textY + 20, layout.fontSizeMedium, colors.text);
  } else if (state === 'final' || state === 'post_interaction') {
    // Show final state: square term zero, maximum area
    const vertexX = graphX + 5 * scaleX;
    const vertexY = graphY + graphH - 25 * scaleY;
    drawCircle(vertexX, vertexY, 5, colors.point);
    drawText('(5,25)', vertexX + 10, vertexY - 10, layout.fontSizeSmall, colors.text);

    const demoRectW = 5 * (fenceW - 30) / 10;
    const demoRectH = 5 * (fenceH - 40) / 10;
    drawRect(rectX, rectY, demoRectW, demoRectH, colors.area);
    drawText('x=5', rectX + demoRectW/2, rectY - 5, layout.fontSizeSmall, colors.text, 'center');
    drawText('10-2x=0?', rectX + demoRectW + 5, rectY + demoRectH/2, layout.fontSizeSmall, colors.text, 'left');

    drawText('平方项为零，面积最大！', textX, textY + 20, layout.fontSizeMedium, colors.text);
  } else if (state === 'paused') {
    // Paused: show intermediate state with pause indicator
    const pointX = graphX + 4 * scaleX;
    const pointY = graphY + graphH - ( -16 + 40 ) * scaleY; // y = -16+40=24
    drawCircle(pointX, pointY, 5, colors.point);
    drawText('(4,24)', pointX + 10, pointY - 10, layout.fontSizeSmall, colors.text);

    const demoRectW = 4 * (fenceW - 30) / 10;
    const demoRectH = 2 * (fenceH - 40) / 10; // 10-8=2
    drawRect(rectX, rectY, demoRectW, demoRectH, colors.area);
    drawText('x=4', rectX + demoRectW/2, rectY - 5, layout.fontSizeSmall, colors.text, 'center');
    drawText('10-2x=2', rectX + demoRectW + 5, rectY + demoRectH/2, layout.fontSizeSmall, colors.text, 'left');

    drawText('已暂停', textX, textY + 20, layout.fontSizeMedium, colors.text);
  } else if (state === 'resumed') {
    // Resumed: similar to key_process but with resume indicator
    const pointX = graphX + 4.5 * scaleX;
    const pointY = graphY + graphH - ( -20.25 + 45 ) * scaleY; // y = -20.25+45=24.75
    drawCircle(pointX, pointY, 5, colors.point);
    drawText('(4.5,24.75)', pointX + 10, pointY - 10, layout.fontSizeSmall, colors.text);

    const demoRectW = 4.5 * (fenceW - 30) / 10;
    const demoRectH = 1 * (fenceH - 40) / 10; // 10-9=1
    drawRect(rectX, rectY, demoRectW, demoRectH, colors.area);
    drawText('x=4.5', rectX + demoRectW/2, rectY - 5, layout.fontSizeSmall, colors.text, 'center');
    drawText('10-2x=1', rectX + demoRectW + 5, rectY + demoRectH/2, layout.fontSizeSmall, colors.text, 'left');

    drawText('继续播放', textX, textY + 20, layout.fontSizeMedium, colors.text);
  }

  api.emit('render_complete');
}
